import multiprocessing
from typing import Any, Callable, Dict, Iterable, Iterator, List, Tuple

import pandas as pd
from pandas.core.window.rolling import RollingGroupby as PandasRollingGroupby

from ..utils import (
    NON_CONSTRUCTOR_WINDOW_ATTRIBUTES,
    WorkerStatus,
    chunk,
    get_group_result_index,
    get_groupby_window_groups,
    get_window_attributes,
)
from .generic import DataType


class RollingGroupBy:
    class Apply(DataType):
        @staticmethod
        def get_chunks(
            nb_workers: int, data: PandasRollingGroupby, *args, **kwargs
        ) -> Iterator[List[Tuple[Any, pd.DataFrame, pd.Index]]]:
            groups = get_groupby_window_groups(data)

            for chunk_ in chunk(len(groups), nb_workers):
                yield groups[chunk_]

        @staticmethod
        def get_work_extra(data: PandasRollingGroupby) -> Dict[str, Any]:
            extra: Dict[str, Any] = {"attributes": get_window_attributes(data)}

            if len(data.obj) == 0:
                # There is nothing to compute: let pandas build the (empty) result, so
                # it has exactly the expected type, index and dtypes.
                extra["empty_result"] = data.apply(lambda _: 0.0)

            return extra

        @staticmethod
        def work(
            data: List[Tuple[Any, pd.DataFrame, pd.Index]],
            user_defined_function: Callable,
            user_defined_function_args: tuple,
            user_defined_function_kwargs: Dict[str, Any],
            extra: Dict[str, Any],
        ) -> pd.DataFrame:
            show_progress_bars: bool = extra["show_progress_bars"]
            master_workers_queue: multiprocessing.Queue = extra["master_workers_queue"]
            worker_index: int = extra["worker_index"]

            if not data:
                return extra["empty_result"]

            def compute_result(
                iteration: int,
                attributes: Dict[str, Any],
                key: Any,
                df: pd.DataFrame,
                group_index: pd.Index,
                user_defined_function: Callable,
                user_defined_function_args: tuple,
                user_defined_function_kwargs: Dict[str, Any],
            ) -> pd.DataFrame:
                item = df.rolling(**attributes).apply(
                    user_defined_function,
                    *user_defined_function_args,
                    **user_defined_function_kwargs,
                )

                item.index = get_group_result_index(key, group_index)

                if show_progress_bars:
                    master_workers_queue.put_nowait(
                        (worker_index, WorkerStatus.Running, iteration)
                    )

                return item

            attributes = dict(extra["attributes"])

            for attribute in NON_CONSTRUCTOR_WINDOW_ATTRIBUTES:
                attributes.pop(attribute, None)

            dfs = (
                compute_result(
                    iteration,
                    attributes,
                    key,
                    df,
                    group_index,
                    user_defined_function,
                    user_defined_function_args,
                    user_defined_function_kwargs,
                )
                for iteration, (key, df, group_index) in enumerate(data)
            )

            return pd.concat(dfs)

        @staticmethod
        def reduce(datas: Iterable[pd.DataFrame], extra: Dict[str, Any]) -> pd.Series:
            return pd.concat(datas, copy=False)
